public class InvalidConversionDemo {
    static int castObject(Object value) { return (Integer) value; }
    static int parseText(String value) { return Integer.parseInt(value); }
    public static void main(String[] args) {
        if ("cast".equals(args[0])) System.out.println(castObject("258"));
        else System.out.println(parseText("258x"));
    }
}
